## Regenerates `src/libunicorn/gen_v2.nim` from the Unicorn headers that
## pkg-config points at. Maintainer tool: run it with `nimble regen`, or
## `nim c tools/gen.nim` (the switches it needs are in `gen.nims`).
##
## One generated file serves every Unicorn 2, so the headers must be those of
## the newest release the bindings support: 2.1.4 or later. The output is the
## same on every run and wherever the headers are installed.
##
## Requirements: the Futhark version pinned in `libunicorn.nimble`, its `opir`
## helper on the PATH, a `clang` on the PATH with the same major version as the
## libclang `opir` was linked against, and Nim >= 2.4.
##
## To generate from another Unicorn than the system one:
## `PKG_CONFIG_PATH=<prefix>/lib/pkgconfig nimble regen`.

import std/[json, os, strutils]
import futhark

proc pkgConfig(query: string): string {.compileTime.} =
  let (output, exitCode) = gorgeEx("pkg-config " & query & " unicorn")
  doAssert exitCode == 0, "pkg-config " & query & " unicorn failed: " & output
  output.strip

proc headerVersion(header: string): string {.compileTime.} =
  ## `UC_API_MAJOR.UC_API_MINOR.UC_API_PATCH` as `unicorn.h` defines them.
  var parts: array[3, string]
  for line in header.splitLines:
    let words = line.splitWhitespace
    if words.len == 3 and words[0] == "#define":
      let index = ["UC_API_MAJOR", "UC_API_MINOR", "UC_API_PATCH"].find(words[1])
      if index >= 0: parts[index] = words[2]
  parts.join(".")

const
  # The variable, not --cflags-only-I: for a Unicorn in /usr pkg-config prints
  # no -I at all, because /usr/include is a default directory.
  includeDir = pkgConfig("--variable=includedir") / "unicorn"
  # From the header rather than from pkg-config, so that the file says what it
  # was really generated from.
  version = headerVersion(staticRead(includeDir / "unicorn.h"))
  numbers = version.split('.')
  major = parseInt(numbers[0])
  output = currentSourcePath().parentDir.parentDir / "src" / "libunicorn" /
           ("gen_v" & $major & ".nim")

static:
  doAssert major == 2, "no bindings are kept for Unicorn " & version
  # One file serves every Unicorn 2: the API only grows, and `raw.nim` guards
  # what an older library lacks. It refers to declarations up to 2.1.4.
  doAssert (parseInt(numbers[1]), parseInt(numbers[2])) >= (1, 4),
    "generate the bindings from Unicorn 2.1.4 or later, not " & version

# C enums whose members are bits to be combined. A Nim enum cannot hold a
# combination of its members, so they become constants of a distinct type
# (declared in `prelude`; `raw.nim` gives them `or`, `and`, `==` and `$`).
const flagEnums = ["uc_mode", "uc_prot", "uc_hook_type"]

const prelude = """
## Unicorn """ & version & """ C API, generated by `tools/gen.nim` with Futhark. Do not edit:
## fix the generator or `raw.nim` instead, then run `nimble regen`.

type
  uc_mode* = distinct uint32
    ## Bit set of `UC_MODE_*` values; combine them with `or`.
  uc_prot* = distinct uint32
    ## Bit set of `UC_PROT_*` values; combine them with `or`.
  uc_hook_type* = distinct uint32
    ## Bit set of `UC_HOOK_*` values; combine them with `or`.
  struct_uc_struct* = object
    ## The engine; only ever used through `ptr uc_engine`.
  struct_uc_context* = object
    ## A saved CPU context; only ever used through `ptr uc_context`.
"""

# `-d:noopaquetypes` (needed for the flag types) also keeps Futhark from
# declaring the two structs the headers only name, so they are declared here.
type # for this compilation; the output gets them from `prelude`
  uc_mode = distinct uint32
  uc_prot = distinct uint32
  uc_hook_type = distinct uint32
  struct_uc_struct = object
  struct_uc_context = object

proc rename(name: string; kind: SymbolKind; partof: string; overloading: var bool): string =
  ## Names Nim cannot spell: `end`, `type` and `ptr` are keywords (Futhark
  ## would emit `end_field`, `type_arg`, ...).
  result = name
  if kind == Field and name == "end": result = "last"       # uc_mem_region.end is inclusive
  elif kind == Argument:
    if name == "type": result = "kind"
    elif name == "end": result = "last"
    elif name == "ptr": result = "host"

proc reshape(opir: JsonNode): JsonNode =
  ## Adjusts what `opir` read from the headers before Futhark turns it into Nim.
  result = newJArray()
  for node in opir:
    let kind = node["kind"].str
    let name = node{"name"}.getStr
    if kind == "enum" and name.len > 5 and name[5 .. ^1] in flagEnums:
      # `enum uc_prot` (named `enum_uc_prot` here) becomes constants of the
      # distinct type `uc_prot`.
      for field in node["fields"]:
        result.add %*{"kind": "const", "file": node["file"], "position": node["position"],
                      "name": field["name"],
                      "value": parseBiggestInt(field["value"].str) and 0xFFFF_FFFF,
                      "type": {"kind": "base", "value": name[5 .. ^1]}}
    elif kind == "typedef" and name in flagEnums:
      discard
    elif node{"file"}.getStr.endsWith("/platform.h"):
      # Compiler plumbing (`MSC_VER_VS2003`, ...), not part of the Unicorn API.
      discard
    else:
      result.add node

# Futhark 0.16.1 only accepts a closure here.
const reshapeCallback: proc (opir: JsonNode): JsonNode {.closure.} = reshape

importc:
  outputPath output
  path includeDir
  renameCallback rename
  addOpirCallback reshapeCallback
  "unicorn.h"

static:
  # Futhark records where each declaration came from; keep that independent of
  # where the headers happened to be installed.
  writeFile(output, prelude &
    readFile(output).replace(includeDir & "/", "unicorn/").strip(leading = false) & "\n")
  echo "wrote ", output, " from the Unicorn ", version, " headers in ", includeDir
